13	int webide_collect_status(struct webide_status_s *st)
14	{
15	  struct mallinfo mi;
16	  struct timespec ts;
17	
18	  memset(st, 0, sizeof(*st));
19	  clock_gettime(CLOCK_MONOTONIC, &ts);
20	  st->uptime_ms = (uint32_t)(ts.tv_sec * 1000u + ts.tv_nsec / 1000000u);
21	
22	  mi = mallinfo();
23	  st->heap_used = (uint32_t)mi.uordblks;
24	  st->heap_free = (uint32_t)mi.fordblks;
25	#ifdef CONFIG_SYSTEM_INFO
26	  st->heap_largest = (uint32_t)mi.mxordblk;
27	#else
28	  st->heap_largest = (uint32_t)mi.mxordblk;
29	#endif
30	
31	  webide_wifi_status(st->essid, sizeof(st->essid),
32	                     st->ip, sizeof(st->ip), &st->wifi_up);
33	  st->running_pid = webide_running_pid();
34	  /* Do not read boot.json here: LittleFS I/O disables cache and
35	   * drops STA. Deploy endpoint updates the file when the user asks.
36	   */
37	  snprintf(st->root, sizeof(st->root), "%s", webide_root());
38	  snprintf(st->chip, sizeof(st->chip), "esp32s3");
39	  snprintf(st->board, sizeof(st->board), "esp32s3-eye");
40	#ifdef CONFIG_SMP
41	  st->cores = CONFIG_SMP_NCPUS;
42	#else
43	  st->cores = 1;
44	#endif
45	  return OK;
46	}
