1	/****************************************************************************
2	 * vendor/webide/src/webide_main.c
3	 *
4	 * Companion service. NSH owns the USB console; this task must not write
5	 * there (printf on the shared tty stalls USB Serial and kills input).
6	 ****************************************************************************/
7	
8	#include "webide.h"
9	
10	#include <errno.h>
11	#include <fcntl.h>
12	#include <sys/stat.h>
13	#include <syslog.h>
14	#include <unistd.h>
15	
16	#include <nuttx/sched.h>
17	
18	#ifdef CONFIG_ARCH_CHIP_ESP32S3
19	extern int ets_printf(const char *fmt, ...);
20	#else
21	#  define ets_printf(...) do { syslog(LOG_INFO, __VA_ARGS__); } while (0)
22	#endif
23	
24	static int webide_http_task(int argc, FAR char *argv[])
25	{
26	  int fd;
27	  int ret;
28	
29	  (void)argc;
30	  (void)argv;
31	
32	  fd = open("/dev/null", O_RDWR);
33	  if (fd >= 0)
34	    {
35	      dup2(fd, STDIN_FILENO);
36	      dup2(fd, STDOUT_FILENO);
37	      dup2(fd, STDERR_FILENO);
38	      if (fd > STDERR_FILENO)
39	        {
40	          close(fd);
41	        }
42	    }
43	
44	  mkdir("/tmp", 0755);
45	  mkdir("/tmp/webide", 0755);
46	  webide_ensure_dirs();
47	  webide_seed_examples();
48	  webide_boot_run();
49	  ets_printf("WebIDE http :%d\n", CONFIG_WEBIDE_PORT);
50	  ret = webide_http_run(CONFIG_WEBIDE_PORT);
51	  ets_printf("WebIDE http exit %d\n", ret);
52	  return ret;
53	}
54	
55	int main(int argc, FAR char *argv[])
56	{
57	  int pid;
58	
59	  (void)argc;
60	  (void)argv;
61	
62	  /* Always return to NSH. Never dup2 the console in this task. */
63	
64	  pid = task_create("webide-http", CONFIG_WEBIDE_PRIORITY,
65	                    CONFIG_WEBIDE_STACKSIZE, webide_http_task, NULL);
66	  if (pid < 0)
67	    {
68	      ets_printf("WebIDE spawn fail %d\n", pid);
69	      return 1;
70	    }
71	
72	  return 0;
73	}
