23	static int send_all(int fd, const char *buf, size_t len)
24	{
25	  size_t sent = 0;
26	
27	  while (sent < len)
28	    {
29	      ssize_t n = send(fd, buf + sent, len - sent, 0);
30	      if (n <= 0)
31	        {
32	          return -1;
33	        }
34	
35	      sent += (size_t)n;
36	    }
37	
38	  return 0;
39	}
40	
41	static int http_reply(int fd, int code, const char *ctype,
42	                      const char *body, size_t blen)
43	{
44	  char hdr[256];
45	  const char *reason = "OK";
46	  int n;
47	
48	  if (code == 400)
49	    {
50	      reason = "Bad Request";
51	    }
52	  else if (code == 404)
53	    {
54	      reason = "Not Found";
55	    }
56	  else if (code == 409)
57	    {
58	      reason = "Conflict";
59	    }
60	  else if (code == 500)
61	    {
62	      reason = "Internal Error";
63	    }
64	
65	  if (!body)
66	    {
67	      body = "";
68	      blen = 0;
69	    }
70	
71	  n = snprintf(hdr, sizeof(hdr),
72	               "HTTP/1.0 %d %s\r\n"
73	               "Content-Type: %s\r\n"
74	               "Content-Length: %u\r\n"
75	               "Cache-Control: no-store\r\n"
76	               "Access-Control-Allow-Origin: *\r\n"
77	               "Connection: close\r\n"
78	               "\r\n",
79	               code, reason, ctype, (unsigned)blen);
80	  if (send_all(fd, hdr, (size_t)n) < 0)
81	    {
82	      return -1;
83	    }
84	
85	  return send_all(fd, body, blen);
86	}
