102	static char *url_query(char *path, const char *key)
103	{
104	  char *q;
105	  char *p;
106	  size_t klen;
107	
108	  q = strchr(path, '?');
109	  if (!q)
110	    {
111	      return NULL;
112	    }
113	
114	  q++;
115	  klen = strlen(key);
116	  while (q && *q)
117	    {
118	      p = strchr(q, '&');
119	      if (strncmp(q, key, klen) == 0 && q[klen] == '=')
120	        {
121	          q += klen + 1;
122	          if (p)
123	            {
124	              *p = '\0';
125	            }
126	
127	          return q;
128	        }
129	
130	      q = p ? p + 1 : NULL;
131	    }
132	
133	  return NULL;
134	}
