136	static void url_decode(char *s)
137	{
138	  char *d = s;
139	
140	  while (*s)
141	    {
142	      if (*s == '+' )
143	        {
144	          *d++ = ' ';
145	          s++;
146	        }
147	      else if (*s == '%' && s[1] && s[2])
148	        {
149	          char hex[3] = { s[1], s[2], 0 };
150	          *d++ = (char)strtol(hex, NULL, 16);
151	          s += 3;
152	        }
153	      else
154	        {
155	          *d++ = *s++;
156	        }
157	    }
158	
159	  *d = '\0';
160	}
