609	static int read_request(int fd, char **body_out, size_t *blen_out)
610	{
611	  char hdr[REQ_HDR];
612	  size_t n = 0;
613	  char *sep;
614	  size_t clen = 0;
615	  char *p;
616	  char *body = NULL;
617	
618	  *body_out = NULL;
619	  *blen_out = 0;
620	
621	  while (n + 1 < sizeof(hdr))
622	    {
623	      ssize_t r = recv(fd, hdr + n, sizeof(hdr) - 1 - n, 0);
624	      if (r <= 0)
625	        {
626	          return -1;
627	        }
628	
629	      n += (size_t)r;
630	      hdr[n] = '\0';
631	      sep = strstr(hdr, "\r\n\r\n");
632	      if (sep)
633	        {
634	          break;
635	        }
636	    }
637	
638	  sep = strstr(hdr, "\r\n\r\n");
639	  if (!sep)
640	    {
641	      return -1;
642	    }
643	
644	  *sep = '\0';
645	  p = hdr;
646	  while ((p = strstr(p, "\r\n")) != NULL)
647	    {
648	      p += 2;
649	      if (strncasecmp(p, "Content-Length:", 15) == 0)
650	        {
651	          clen = (size_t)atoi(p + 15);
652	          break;
653	        }
654	    }
655	
656	  if (clen > WEBIDE_MAX_FILE)
657	    {
658	      return -1;
659	    }
660	
661	  if (clen > 0)
662	    {
663	      size_t have;
664	      char *after = sep + 4;
665	
666	      have = n - (size_t)(after - hdr);
667	      body = malloc(clen + 1);
668	      if (!body)
669	        {
670	          return -1;
671	        }
672	
673	      if (have > clen)
674	        {
675	          have = clen;
676	        }
677	
678	      memcpy(body, after, have);
679	      while (have < clen)
680	        {
681	          ssize_t r = recv(fd, body + have, clen - have, 0);
682	          if (r <= 0)
683	            {
684	              free(body);
685	              return -1;
686	            }
687	
688	          have += (size_t)r;
689	        }
690	
691	      body[clen] = '\0';
692	    }
693	
694	  *body_out = body;
695	  *blen_out = clen;
696	  return handle_request(fd, hdr, n, body, clen);
697	}
