  st->heap_largest = (uint32_t)mi.mxordblk;
#endif

  webide_wifi_status(st->essid, sizeof(st->essid),
                     st->ip, sizeof(st->ip), &st->wifi_up);
  st->running_pid = webide_running_pid();
  /* Do not read boot.json here: LittleFS I/O disables cache and
   * drops STA. Deploy endpoint updates the file when the user asks.
   */
  snprintf(st->root, sizeof(st->root), "%s", webide_root());
  snprintf(st->chip, sizeof(st->chip), "esp32s3");
  snprintf(st->board, sizeof(st->board), "esp32s3-eye");
#ifdef CONFIG_SMP
  st->cores = CONFIG_SMP_NCPUS;
#else
  st->cores = 1;
#endif
  return OK;
}
```

（注意 25-29 行那个 `#ifdef CONFIG_SYSTEM_INFO` 两个分支完全一样，是无意义的死分支。）

**JSON 用 cJSON 拼，不是 snprintf。** 拼装点在 `vendor\webide\src\webide_http.c:162-194`（`handle_status()`），流程是 `cJSON_CreateObject()` → 一堆 `cJSON_Add*ToObject` → `cJSON_PrintUnformatted()` → `cJSON_Delete()` → `http_json()` → `free(js)`。仅 `http_err()`（`webide_http.c:94-100`）用了 snprintf 手拼。

