**渲染状态字段的 JS（`index.html:556-569`）：**

```js
async function status(){
  try{
    const s=await api('/api/status');
    running=s.running_pid>0;
    $('#p-run').textContent=running?('运行中 '+s.running_pid):'空闲';
    $('#p-wifi').textContent=s.essid?s.essid:'未连接';
    $('#p-ip').textContent=s.ip||'无地址';
    $('#p-mem').textContent=fmt(s.heap_used)+' / '+fmt(s.heap_used+s.heap_free);
    $('#s-chip').textContent=s.chip; $('#s-board').textContent=s.board;
    $('#s-cores').textContent=s.cores; $('#s-up').textContent=sec(s.uptime_ms);
    $('#s-used').textContent=fmt(s.heap_used); $('#s-free').textContent=fmt(s.heap_free);
    $('#s-root').textContent=s.root;
  }catch(e){}
