function fmt(n){ if(n>1048576) return (n/1048576).toFixed(1)+'MB'; if(n>1024) return (n/1024).toFixed(0)+'KB'; return n+'B' }
function sec(ms){ const s=Math.floor(ms/1000); return Math.floor(s/3600)+'h '+Math.floor(s%3600/60)+'m' }
