## 7. `webide_main.c` 全文

`C:\Users\flash\Desktop\新建文件夹\新建文件夹\esp32_openvela-main\esp32_openvela-main\vendor\webide\src\webide_main.c`（共 73 行）：

```c
/****************************************************************************
 * vendor/webide/src/webide_main.c
 *
 * Companion service. NSH owns the USB console; this task must not write
 * there (printf on the shared tty stalls USB Serial and kills input).
 ****************************************************************************/

#include "webide.h"

#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <syslog.h>
#include <unistd.h>

#include <nuttx/sched.h>

#ifdef CONFIG_ARCH_CHIP_ESP32S3
extern int ets_printf(const char *fmt, ...);
#else
#  define ets_printf(...) do { syslog(LOG_INFO, __VA_ARGS__); } while (0)
#endif

static int webide_http_task(int argc, FAR char *argv[])
{
  int fd;
  int ret;

  (void)argc;
  (void)argv;

  fd = open("/dev/null", O_RDWR);
  if (fd >= 0)
    {
      dup2(fd, STDIN_FILENO);
      dup2(fd, STDOUT_FILENO);
      dup2(fd, STDERR_FILENO);
      if (fd > STDERR_FILENO)
        {
          close(fd);
        }
    }

  mkdir("/tmp", 0755);
  mkdir("/tmp/webide", 0755);
  webide_ensure_dirs();
  webide_seed_examples();
  webide_boot_run();
  ets_printf("WebIDE http :%d\n", CONFIG_WEBIDE_PORT);
  ret = webide_http_run(CONFIG_WEBIDE_PORT);
  ets_printf("WebIDE http exit %d\n", ret);
  return ret;
}

int main(int argc, FAR char *argv[])
{
  int pid;

  (void)argc;
  (void)argv;

  /* Always return to NSH. Never dup2 the console in this task. */

  pid = task_create("webide-http", CONFIG_WEBIDE_PRIORITY,
                    CONFIG_WEBIDE_STACKSIZE, webide_http_task, NULL);
  if (pid < 0)
    {
      ets_printf("WebIDE spawn fail %d\n", pid);
      return 1;
    }

  return 0;
}
```

